You can easily copy the original drawGameTitle and make a second one.
Save this as a plugin and edit the values to suite your need.
JavaScript:
Scene_Title.prototype.createForeground = function() {
    this._gameTitleSprite = new Sprite(
        new Bitmap(Graphics.width, Graphics.height)
    );
    this.addChild(this._gameTitleSprite);
    if ($dataSystem.optDrawTitle) {
        this.drawGameTitle();
        this.drawGameTitle2();
    }
};
Scene_Title.prototype.drawGameTitle = function() {
    const x = 20;
    const y = Graphics.height / 4;
    const maxWidth = Graphics.width - x * 2;
    const text = $dataSystem.gameTitle;
    const bitmap = this._gameTitleSprite.bitmap;
    bitmap.fontFace = $gameSystem.mainFontFace();
    bitmap.outlineColor = "black";
    bitmap.outlineWidth = 8;
    bitmap.fontSize = 72;
    bitmap.drawText(text, x, y, maxWidth, 48, "center");
};
Scene_Title.prototype.drawGameTitle2 = function() {
    const x = 20;
    const y = Graphics.height / 4 + 80;
    const maxWidth = Graphics.width - x * 2;
    const text = 'v1.1.0';
    const bitmap = this._gameTitleSprite.bitmap;
    bitmap.fontFace = $gameSystem.mainFontFace();
    bitmap.outlineColor = "black";
    bitmap.outlineWidth = 2;
    bitmap.fontSize = 12;
    bitmap.drawText(text, x, y, maxWidth, 24, "center");
};
